import {
  ErrorKind,
  PolicyMode,
  CreateFieldLifetime,
  CreateFieldNetworkOutboundCidrsEntries,
  CreateFieldNetworkOutboundDomainsEntries,
  CreateFieldNetworkOutboundProxyUrl,
  CreateFieldRuntimeLanguage,
  CreateFieldSecuritySecretsEnvironmentVariable,
  validCidr,
  validDomain,
  validEnvName,
} from "@sandbox-kit/sandbox";
import type { CreateOptions } from "@sandbox-kit/sandbox";
import { providerError } from "../errors.js";

type PublicAction = NonNullable<
  NonNullable<CreateOptions["lifetime"]>["idleStop"]
>;

// validateProviderCreate rejects creation settings this provider cannot honor.
// Rules are inventoried in specs/providers/daytona.yaml checks.
export function validateProviderCreate(request: CreateOptions): void {
  const language = request.runtime?.language;
  if (
    language !== undefined &&
    language !== "python" &&
    language !== "javascript" &&
    language !== "typescript"
  ) {
    providerError({
      kind: ErrorKind.Unsupported,
      operation: "create",
      field: CreateFieldRuntimeLanguage,
      message: "runtime.language is outside supported values",
    });
  }
  const outboundProxyUrl = request.network?.outboundProxyUrl;
  if (outboundProxyUrl !== undefined && !validHttpUrl(outboundProxyUrl)) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldNetworkOutboundProxyUrl,
      message: "network.outbound_proxy_url is outside supported values",
    });
  }
  for (const value of request.network?.outboundCidrs ?? []) {
    if (!validCidr(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldNetworkOutboundCidrsEntries,
        message: "network.outbound_cidrs.entries is outside supported values",
      });
    }
  }
  for (const value of request.network?.outboundDomains ?? []) {
    if (!validDomain(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldNetworkOutboundDomainsEntries,
        message: "network.outbound_domains.entries is outside supported values",
      });
    }
  }
  for (const item of request.security?.secrets ?? []) {
    const environmentVariable = item.environmentVariable;
    if (
      environmentVariable !== undefined &&
      !validEnvName(environmentVariable)
    ) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldSecuritySecretsEnvironmentVariable,
        message:
          "security.secrets.environment_variable is outside supported values",
      });
    }
  }
  if (
    delayed(request.lifetime?.idleStop) &&
    delayed(request.lifetime?.idlePause)
  ) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldLifetime,
      message: "incompatible lifetime policies",
    });
  }
  if (
    delayed(request.lifetime?.idlePause) &&
    request.lifetime?.ephemeral === true
  ) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldLifetime,
      message: "incompatible lifetime policies",
    });
  }
  if (
    delayed(request.lifetime?.idlePause) &&
    immediate(request.lifetime?.stoppedDelete)
  ) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldLifetime,
      message: "incompatible lifetime policies",
    });
  }
  if (
    delayed(request.lifetime?.stoppedDelete) &&
    request.lifetime?.ephemeral === true
  ) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldLifetime,
      message: "incompatible lifetime policies",
    });
  }
  if (
    delayed(request.lifetime?.stoppedArchive) &&
    request.lifetime?.ephemeral === true
  ) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldLifetime,
      message: "incompatible lifetime policies",
    });
  }
}

function delayed(policy: PublicAction | undefined): boolean {
  return (
    (policy?.mode ?? PolicyMode.Default) === PolicyMode.After &&
    policy?.after !== undefined &&
    policy.after > 0
  );
}

function immediate(policy: PublicAction | undefined): boolean {
  return (
    (policy?.mode ?? PolicyMode.Default) === PolicyMode.After &&
    policy?.after !== undefined &&
    policy.after === 0
  );
}

function validHttpUrl(value: string): boolean {
  try {
    const parsed = new URL(value);
    return (
      parsed.hostname !== "" &&
      (parsed.protocol === "http:" || parsed.protocol === "https:")
    );
  } catch {
    return false;
  }
}

import {
  ErrorKind,
  CreateFieldEnvironment,
  CreateFieldNetworkInboundCidrsEntries,
  CreateFieldNetworkOutboundCidrsEntries,
  CreateFieldNetworkOutboundDomainsEntries,
  CreateFieldPlacementCloud,
  CreateFieldResourcesCpuCores,
  CreateFieldResourcesMemoryMib,
  CreateFieldRuntimeWorkingDirectory,
  validCidr,
  validDomain,
  validEnvName,
} from "@sandbox-kit/sandbox";
import type { CreateOptions } from "@sandbox-kit/sandbox";
import { providerError } from "../errors.js";

// validateProviderCreate rejects creation settings this provider cannot honor.
// Rules are inventoried in specs/providers/modal.yaml checks.
export function validateProviderCreate(request: CreateOptions): void {
  const cpuCores = request.resources?.cpuCores;
  if (cpuCores !== undefined && cpuCores < 0.125) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldResourcesCpuCores,
      message: "resources.cpu_cores is outside supported values",
    });
  }
  const memoryMib = request.resources?.memoryMib;
  if (memoryMib !== undefined && memoryMib < BigInt("128")) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldResourcesMemoryMib,
      message: "resources.memory_mib is outside supported values",
    });
  }
  const workingDirectory = request.runtime?.workingDirectory;
  if (workingDirectory !== undefined && !workingDirectory.startsWith("/")) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "create",
      field: CreateFieldRuntimeWorkingDirectory,
      message: "runtime.working_directory is outside supported values",
    });
  }
  const cloud = request.placement?.cloud;
  if (
    cloud !== undefined &&
    cloud !== "aws" &&
    cloud !== "gcp" &&
    cloud !== "oci" &&
    cloud !== "auto"
  ) {
    providerError({
      kind: ErrorKind.Unsupported,
      operation: "create",
      field: CreateFieldPlacementCloud,
      message: "placement.cloud is outside supported values",
    });
  }
  for (const value of request.network?.outboundCidrs ?? []) {
    if (value !== "" && !validCidr(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldNetworkOutboundCidrsEntries,
        message: "network.outbound_cidrs.entries is outside supported values",
      });
    }
  }
  for (const value of request.network?.inboundCidrs ?? []) {
    if (!validCidr(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldNetworkInboundCidrsEntries,
        message: "network.inbound_cidrs.entries is outside supported values",
      });
    }
  }
  for (const value of request.network?.outboundDomains ?? []) {
    if (value !== "" && !validDomain(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldNetworkOutboundDomainsEntries,
        message: "network.outbound_domains.entries is outside supported values",
      });
    }
  }
  for (const value of Object.keys(request.environment ?? {})) {
    if (!validEnvName(value)) {
      providerError({
        kind: ErrorKind.InvalidArgument,
        operation: "create",
        field: CreateFieldEnvironment,
        message: "environment is outside supported values",
      });
    }
  }
}

